import type { TransitMode } from "@/types";

// Scheduled departures for every stop, derived from the TLT GTFS feed
// (valid Sep 12 - Oct 31, 2026). Times are minutes past midnight; a single
// number is one departure, [start,end,step] is a regular interval.
// w = Mon-Fri, s = Saturday, u = Sunday. Times past 24:00 belong to the
// same service day (late-night trips).
export type TimeSpec = number | [number, number, number];

export interface LineTimetable {
  /** Line number as shown on the vehicle. */
  n: string;
  m: TransitMode;
  /** Index into DESTS (destination shown on the vehicle). */
  g: number;
  w: TimeSpec[];
  s: TimeSpec[];
  u: TimeSpec[];
}

